import{_ as e,o as n,c as i,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Armadura y mitigación","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/armor-and-mitigation.md","filePath":"es/game-design/combat/armor-and-mitigation.md"}'),o={name:"es/game-design/combat/armor-and-mitigation.md"};function r(d,a,s,c,l,m){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="armor-and-mitigation" tabindex="-1">Armadura y mitigación <a class="header-anchor" href="#armor-and-mitigation" aria-label="Enlace permanente a &quot;Armadura y mitigación&quot;">​</a></h1><p><strong>Estado del diseño: Aceptado para la cobertura localizada y la durabilidad compartida; Experimental para el adaptador heredado; Propuesto para las interacciones de materiales y estado. Implementación: adaptador de Stage 2A, no el modelo ampliado de materiales descrito abajo.</strong></p><p><a href="/Syrolands-Public/es/guide/combat/armor-and-protection.html">Guía del jugador</a> · <a href="/Syrolands-Public/es/game-design/combat/overview.html">Fundamentos de combate</a></p><h2 id="accepted-foundation-and-existing-bridge" tabindex="-1">Fundamento con estado Aceptado y adaptación existente <a class="header-anchor" href="#accepted-foundation-and-existing-bridge" aria-label="Enlace permanente a &quot;Fundamento con estado Aceptado y adaptación existente&quot;">​</a></h2><p>La armadura protege la región que cubre y debería proteger tanto la salud global como la integridad local, posiblemente mediante cálculos diferentes más adelante. El adaptador actual de armadura heredada define las categorías exactas de contacto, los pesos de cobertura, el orden de procesamiento y el desgaste compartido. Las regiones corporales son más precisas que el equipo heredado: mangas y perneras protegen ambos lados mediante una pieza cada una; los guantes son un par compartido para contactos en las manos dentro de los brazos.</p><p>El adaptador resuelve un contacto real, aplica una sola vez la mitigación del escudo y la pieza seleccionada, y conserva la mitigación virtual y mágica heredada. La ausencia de armadura no vuelve a sortear la ubicación. Durabilidad cero no es sinónimo de eliminación; un golpe que rompe la armadura conserva su mitigación y los posteriores pueden encontrar la zona expuesta. La integridad corporal y la durabilidad del objeto siguen siendo estados separados. Esto es una adaptación a la <a href="/Syrolands-Public/es/game-design/combat/damage.html">política experimental aceptada de trauma</a>, no evidencia de penetración específica por material ni de transmisión de trauma ajustada independientemente.</p><h2 id="proposed-physical-interactions" tabindex="-1">Interacciones físicas con estado Propuesto <a class="header-anchor" href="#proposed-physical-interactions" aria-label="Enlace permanente a &quot;Interacciones físicas con estado Propuesto&quot;">​</a></h2><p>La cobertura, la ubicación del impacto, la familia de ataque, el material, el estado, la penetración/desviación y el trauma transmitido deberían importar. Una única puntuación genérica de AR no debería definir el modelo final. Las siguientes son direcciones de investigación, no clasificaciones de resistencia ni tablas numéricas:</p><table tabindex="0"><thead><tr><th>Familia de armadura</th><th>Compromiso con estado Propuesto para investigar</th></tr></thead><tbody><tr><td>Placas</td><td>Protección contra cortes, desviación, deformación e impacto transmitido frente a carga</td></tr><tr><td>Malla</td><td>Cobertura y construcción flexible frente a perforación y transmisión contundente</td></tr><tr><td>Cuero</td><td>Variación de material y estado frente a protección, peso y movilidad</td></tr><tr><td>Tela / protección acolchada / por capas</td><td>Amortiguación y capas frente a protección contra cortes/perforaciones y carga</td></tr></tbody></table><p>Por ejemplo, una placa puede detener un corte y transmitir trauma contundente. Esto no especifica cuánto, no garantiza inmunidad ni autoriza sustituir el prototipo de residual ×2 por una segunda fórmula. El orden de capas, los límites de acumulación y la selección de contacto más allá del adaptador siguen Sin resolver. La conducta de armaduras y armas debería evaluarse junto con las <a href="/Syrolands-Public/es/game-design/combat/weapons-and-damage.html">familias de daño</a>.</p><h2 id="condition-inspection-and-maintenance" tabindex="-1">Estado, inspección y mantenimiento <a class="header-anchor" href="#condition-inspection-and-maintenance" aria-label="Enlace permanente a &quot;Estado, inspección y mantenimiento&quot;">​</a></h2><p>Los efectos del estado con estado Propuesto incluyen desgaste del filo de armas, deformación, correas o costuras debilitadas, daño estructural y rendimiento funcional reducido. Son ejemplos de degradación, no estados recién implementados. La durabilidad existente no debe presentarse como prueba de que todas estas formas estén simuladas.</p><p><a href="/Syrolands-Public/es/game-design/professions/blacksmithing.html">Blacksmithing</a> y <a href="/Syrolands-Public/es/game-design/professions/tailoring.html">Tailoring</a> aportan inspección, conocimiento de materiales y mantenimiento propuestos para sus ámbitos de equipo. <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">Arms Lore</a> aporta interpretación del equipo de combate; la inspección ampliada está aplazada. <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html#weapon-quality-dimensions">Calidad de fabricación</a> sigue siendo la fuente de las dimensiones de calidad y Functional Retention, evitando un modelo de durabilidad rival aquí.</p><p>El desgaste puede crear oportunidades tácticas sin garantizar que la armadura se rompa antes de que una región llegue a Disabled. Las reparaciones, la calidad rara y los rasgos deben preservar la <a href="/Syrolands-Public/es/game-design/equipment-and-loot.html">pérdida significativa y la posibilidad de reemplazo</a>. No se aprueba ninguna regla nueva de conservación o seguro.</p><h2 id="related-design" tabindex="-1">Diseño relacionado <a class="header-anchor" href="#related-design" aria-label="Enlace permanente a &quot;Diseño relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/status-and-open-questions.html">Estado y decisiones sin resolver</a></p>',16)])])}const g=e(o,[["render",r]]);export{u as __pageData,g as default};
